import React, { useState, useRef, useEffect } from 'react';

function formatTime(s) {
  if (!s || isNaN(s)) return '0:00';
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, '0')}`;
}

export default function Player({ track }) {
  const [playing, setPlaying] = useState(false);
  const [current, setCurrent] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const audioRef = useRef(null);

  useEffect(() => {
    if (track?.preview) {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.src = track.preview;
        audioRef.current.volume = volume;
        if (playing) audioRef.current.play().catch(() => {});
      }
    }
  }, [track]);

  useEffect(() => {
    if (!audioRef.current) return;
    if (playing) audioRef.current.play().catch(() => setPlaying(false));
    else audioRef.current.pause();
  }, [playing]);

  function onTimeUpdate() { setCurrent(audioRef.current.currentTime); }
  function onLoadedMetadata() { setDuration(audioRef.current.duration); }
  function onEnded() { setPlaying(false); setCurrent(0); }
  function seek(e) {
    const rect = e.currentTarget.getBoundingClientRect();
    const ratio = (e.clientX - rect.left) / rect.width;
    const t = ratio * duration;
    audioRef.current.currentTime = t;
    setCurrent(t);
  }

  const progress = duration ? (current / duration) * 100 : 0;

  const bars = [1,2,3,4];

  return (
    <footer style={styles.player}>
      <audio ref={audioRef} onTimeUpdate={onTimeUpdate} onLoadedMetadata={onLoadedMetadata} onEnded={onEnded} />

      {/* Track Info */}
      <div style={styles.trackInfo}>
        <div style={styles.thumb}>
          {track?.thumb ? <img src={track.thumb} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 8 }} /> :
            <div style={styles.thumbPlaceholder} />}
          {playing && <div style={styles.bars}>{bars.map(i => <div key={i} style={{ ...styles.bar, animationDelay: `${i * 0.15}s` }} />)}</div>}
        </div>
        <div>
          <div style={styles.trackName}>{track?.name || 'No track selected'}</div>
          <div style={styles.trackArtist}>{track?.artist || '—'}</div>
        </div>
        <button style={styles.heartBtn}>♡</button>
      </div>

      {/* Controls */}
      <div style={styles.controls}>
        <div style={styles.controlBtns}>
          <button style={styles.ctrlBtn}>⇄</button>
          <button style={styles.ctrlBtn}>⏮</button>
          <button style={styles.playBtn} onClick={() => setPlaying(p => !p)}>
            {playing ? '⏸' : '▶'}
          </button>
          <button style={styles.ctrlBtn}>⏭</button>
          <button style={styles.ctrlBtn}>↻</button>
        </div>
        <div style={styles.progressRow}>
          <span style={styles.time}>{formatTime(current)}</span>
          <div style={styles.progressBar} onClick={seek}>
            <div style={{ ...styles.progressFill, width: `${progress}%` }}>
              <div style={styles.progressDot} />
            </div>
          </div>
          <span style={styles.time}>{formatTime(duration)}</span>
        </div>
      </div>

      {/* Volume */}
      <div style={styles.volumeArea}>
        <span style={{ fontSize: 14, color: 'var(--muted)' }}>🔊</span>
        <input type="range" min={0} max={1} step={0.01} value={volume}
          onChange={e => { setVolume(+e.target.value); if (audioRef.current) audioRef.current.volume = +e.target.value; }}
          style={styles.volumeSlider} />
      </div>
    </footer>
  );
}

const styles = {
  player: {
    height: 72, background: 'linear-gradient(90deg, #1a0a2e, #0d1b4b)', borderTop: '1px solid var(--border)',
    display: 'flex', alignItems: 'center', padding: '0 24px', gap: 24, flexShrink: 0,
  },
  trackInfo: { display: 'flex', alignItems: 'center', gap: 14, width: 280, minWidth: 200 },
  thumb: { width: 44, height: 44, borderRadius: 8, background: 'var(--surface2)', overflow: 'hidden', position: 'relative', flexShrink: 0 },
  thumbPlaceholder: { width: '100%', height: '100%', background: 'linear-gradient(135deg, var(--purple), var(--blue))' },
  bars: { position: 'absolute', bottom: 4, left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: 2, alignItems: 'flex-end' },
  bar: { width: 3, background: 'white', borderRadius: 2, animation: 'barAnim 0.8s ease-in-out infinite' },
  trackName: { fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 13, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 160 },
  trackArtist: { fontSize: 11, color: 'var(--muted)', marginTop: 2 },
  heartBtn: { background: 'none', border: 'none', color: 'var(--muted)', cursor: 'pointer', fontSize: 16, marginLeft: 'auto' },
  controls: { flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 },
  controlBtns: { display: 'flex', alignItems: 'center', gap: 20 },
  ctrlBtn: { background: 'none', border: 'none', color: 'var(--muted)', cursor: 'pointer', fontSize: 16, padding: 4 },
  playBtn: {
    width: 38, height: 38, borderRadius: '50%', background: 'linear-gradient(135deg, var(--pink), var(--purple))',
    border: 'none', color: 'white', cursor: 'pointer', fontSize: 15, display: 'flex', alignItems: 'center', justifyContent: 'center',
    boxShadow: '0 0 20px rgba(247,37,133,0.4)',
  },
  progressRow: { display: 'flex', alignItems: 'center', gap: 10, width: '100%', maxWidth: 400 },
  time: { fontSize: 11, color: 'var(--muted)', width: 32, flexShrink: 0, textAlign: 'center' },
  progressBar: { flex: 1, height: 4, background: 'var(--surface2)', borderRadius: 2, cursor: 'pointer', position: 'relative' },
  progressFill: { height: '100%', background: 'linear-gradient(90deg, var(--pink), var(--blue))', borderRadius: 2, position: 'relative', transition: 'width .1s' },
  progressDot: { width: 10, height: 10, borderRadius: '50%', background: 'white', position: 'absolute', right: -5, top: -3 },
  volumeArea: { display: 'flex', alignItems: 'center', gap: 10, width: 140 },
  volumeSlider: { flex: 1, accentColor: 'var(--pink)', cursor: 'pointer' },
};
